public String abbreviation(String a, String b) {
    return solve(a, b, 0, 0) ? "YES" : "NO";
}

private boolean solve(String a, String b, int i, int j) {
    if (j == b.length()) {
        for (int k = i; k < a.length(); k++) {
            if (Character.isUpperCase(a.charAt(k))) return false;
        }
        return true;
    }
    if (i == a.length()) return false;
    char ca = a.charAt(i);
    if (Character.isUpperCase(ca)) {
        return ca == b.charAt(j) && solve(a, b, i + 1, j + 1);
    }
    boolean capitalize = Character.toUpperCase(ca) == b.charAt(j)
            && solve(a, b, i + 1, j + 1);
    boolean delete = solve(a, b, i + 1, j);
    return capitalize || delete;
}

