def abbreviation(self, a: str, b: str) -> str:
    def solve(i: int, j: int) -> bool:
        if j == len(b):
            return all(not a[k].isupper() for k in range(i, len(a)))
        if i == len(a):
            return False
        ca = a[i]
        if ca.isupper():
            return ca == b[j] and solve(i + 1, j + 1)
        capitalize = ca.upper() == b[j] and solve(i + 1, j + 1)
        delete = solve(i + 1, j)
        return capitalize or delete
    return "YES" if solve(0, 0) else "NO"

