public String abbreviation(String a, String b) {
    int n = a.length(), m = b.length();
    boolean[][] dp = new boolean[n + 1][m + 1];
    dp[0][0] = true;
    for (int i = 1; i <= n; i++) {
        char ca = a.charAt(i - 1);
        for (int j = 0; j <= m; j++) {
            if (Character.isUpperCase(ca)) {
                if (j > 0 && ca == b.charAt(j - 1)) {
                    dp[i][j] = dp[i - 1][j - 1];
                }
            } else {
                dp[i][j] = dp[i - 1][j];
                if (j > 0 && Character.toUpperCase(ca) == b.charAt(j - 1)) {
                    dp[i][j] = dp[i][j] || dp[i - 1][j - 1];
                }
            }
        }
    }
    return dp[n][m] ? "YES" : "NO";
}

