public String abbreviation(String a, String b) {
    int n = a.length(), m = b.length();
    boolean[] prev = new boolean[m + 1];
    prev[0] = true;
    for (int i = 1; i <= n; i++) {
        char ca = a.charAt(i - 1);
        boolean[] cur = new boolean[m + 1];
        cur[0] = prev[0] && Character.isLowerCase(ca);
        for (int j = 1; j <= m; j++) {
            if (Character.isUpperCase(ca)) {
                if (ca == b.charAt(j - 1)) cur[j] = prev[j - 1];
            } else {
                cur[j] = prev[j];
                if (Character.toUpperCase(ca) == b.charAt(j - 1)) {
                    cur[j] = cur[j] || prev[j - 1];
                }
            }
        }
        prev = cur;
    }
    return prev[m] ? "YES" : "NO";
}

